def is_palindrome(n: int) -> bool:
    if n < 0:
        return False
    original = n
    rev = 0
    while n:
        rev = rev * 10 + n % 10
        n //= 10
    return rev == original

def is_palindrome_half(n: int) -> bool:
    if n < 0 or (n % 10 == 0 and n != 0):
        return False
    rev = 0
    while n > rev:
        rev = rev * 10 + n % 10
        n //= 10
    return n == rev or n == rev // 10
